<script>
  import { page } from '$app/state';
  import { site } from '#lib/site.js';

  /**
   * Share cards live in static/images/og/ (1200×630), generated by scripts/og-images.py
   * @type {{
   *   title?: string,
   *   description: string,
   *   image?: string,
   *   imageAlt?: string
   * }}
   */
  let {
    title,
    description,
    image = '/images/og/home.jpg',
    imageAlt = 'Platinum Choice Consulting logo: helping organizations succeed through people'
  } = $props();

  const fullTitle = $derived(title ? `${title} | ${site.name}` : site.name);
  const canonical = $derived(new URL(page.url.pathname, site.url).href);
  const imageUrl = $derived(new URL(image, site.url).href);
</script>

<svelte:head>
  <title>{fullTitle}</title>
  <meta name="description" content={description} />
  <link rel="canonical" href={canonical} />

  <meta property="og:type" content="website" />
  <meta property="og:locale" content="en_US" />
  <meta property="og:site_name" content={site.name} />
  <meta property="og:title" content={fullTitle} />
  <meta property="og:description" content={description} />
  <meta property="og:url" content={canonical} />
  <meta property="og:image" content={imageUrl} />
  <meta property="og:image:width" content="1200" />
  <meta property="og:image:height" content="630" />
  <meta property="og:image:alt" content={imageAlt} />

  <meta name="twitter:card" content="summary_large_image" />
  <meta name="twitter:title" content={fullTitle} />
  <meta name="twitter:description" content={description} />
  <meta name="twitter:image" content={imageUrl} />
  <meta name="twitter:image:alt" content={imageAlt} />
</svelte:head>
